/* TechMemo local prototype. Browser state is demonstration-only, not an access-control boundary. */
(() => {
  'use strict';
  const STORE_KEY = 'techmemo-prototype-v1';
  const STANDARDS = {
    'IFRS 15': {label:'IFRS 15 — Revenue from Contracts with Customers', focus:'Identify the contract and performance obligations, assess whether promised goods or services are distinct, and evaluate the related revenue recognition pattern.', url:'https://www.ifrs.org/issued-standards/list-of-standards/ifrs-15-revenue-from-contracts-with-customers/', secondary:'https://www.iasplus.com/en/standards/ifrs/ifrs15'},
    'IFRS 16': {label:'IFRS 16 — Leases', focus:'Assess whether the arrangement contains a lease, the identified asset, the right to control its use, and relevant measurement considerations.',url:'https://www.ifrs.org/issued-standards/list-of-standards/ifrs-16-leases/', secondary:'https://www.iasplus.com/en/standards/ifrs/ifrs16'},
    'IAS 36': {label:'IAS 36 — Impairment of Assets', focus:'Consider indicators of impairment, cash-generating units, recoverable amounts, assumptions and required recognition or disclosures.',url:'https://www.iasplus.com/en/standards/ias/ias36',secondary:'https://www.iasplus.com/en/standards/ias/ias36'},
    'IFRS 3': {label:'IFRS 3 — Business Combinations', focus:'Assess whether the transaction is a business combination, identify the acquirer, and evaluate acquisition-date recognition and measurement.',url:'https://www.iasplus.com/en/standards/ifrs/ifrs3',secondary:'https://www.iasplus.com/en/standards/ifrs/ifrs3'}
  };
  const users = [
    {id:'u1',name:'Ava Morgan',role:'Technical Accounting Manager',org:'o1',color:'green'},
    {id:'u2',name:'Daniel Chen',role:'Legal Counsel',org:'o1',color:'blue'},
    {id:'u3',name:'Priya Shah',role:'Sales Director',org:'o1',color:'purple'},
    {id:'u4',name:'Marcus Lee',role:'Financial Controller',org:'o1',color:'orange'},
    {id:'u5',name:'Evelyn Reed',role:'Accounting Reviewer',org:'o1',color:'teal'},
    {id:'u6',name:'Olivia Park',role:'Accounting Manager',org:'o2',color:'purple'}
  ];
  function initialState(){return {
    user:'u1',workspace:'w1',tab:'memo',view:'workspace',channel:'c1',
    organizations:[{id:'o1',name:'Northstar Group',domain:'northstar.example'},{id:'o2',name:'Harbor & Co.',domain:'harbor.example'}],
    workspaces:[
      {id:'w1',org:'o1',name:'Revenue recognition review',code:'ACC-2026-014',standard:'IFRS 15',status:'In progress',owner:'u1',date:'FY 2026',description:'Assess whether implementation and customization services in the Northstar enterprise software agreement represent distinct performance obligations under IFRS 15.',members:['u1','u2','u3','u4','u5'],created:'2026-11-16'},
      {id:'w2',org:'o1',name:'Lease modification analysis',code:'ACC-2026-009',standard:'IFRS 16',status:'In progress',owner:'u1',date:'FY 2026',description:'Determine the accounting implications of an extension and revised consideration for the regional office lease.',members:['u1','u4'],created:'2026-11-08'},
      {id:'w3',org:'o2',name:'Goodwill impairment review',code:'ACC-2026-032',standard:'IAS 36',status:'Draft',owner:'u6',date:'FY 2026',description:'Assess whether indicators of impairment warrant a recoverable amount calculation for the retail cash-generating unit.',members:['u6'],created:'2026-11-21'}
    ],
    conversations:[
      {id:'c1',workspace:'w1',kind:'general',name:'General discussion',members:[]},
      {id:'c2',workspace:'w1',kind:'direct',name:'Legal Counsel',members:['u1','u2']},
      {id:'c3',workspace:'w1',kind:'direct',name:'Sales Director',members:['u1','u3']},
      {id:'c4',workspace:'w1',kind:'group',name:'Finance review',members:['u1','u4','u5']},
      {id:'c5',workspace:'w2',kind:'general',name:'General discussion',members:[]},
      {id:'c6',workspace:'w3',kind:'general',name:'General discussion',members:[]}
    ],
    messages:[
      {id:'m1',channel:'c1',author:'u1',text:'Welcome to the IFRS 15 review. Please share facts relating to the implementation, customization and contract terms.',time:'09:14',date:'2026-11-19'},
      {id:'m2',channel:'c1',author:'u3',text:'The software is available to the customer on delivery. Implementation services are scoped separately in the statement of work.',time:'09:28',date:'2026-11-19'},
      {id:'m3',channel:'c1',author:'u4',text:'We should confirm whether customization significantly modifies the software before reaching a conclusion.',time:'10:02',date:'2026-11-19'},
      {id:'m4',channel:'c2',author:'u1',text:'Can you confirm whether the customer can terminate implementation separately? Please keep this discussion private until we approve the relevant facts.',time:'11:11',date:'2026-11-20'},
      {id:'m5',channel:'c2',author:'u2',text:'The draft agreement permits separate termination of optional implementation services under clause 8.2, subject to notice. Legal has not yet completed its final review.',time:'11:23',date:'2026-11-20'},
      {id:'m6',channel:'c3',author:'u1',text:'Can the customer use the core platform without customization?',time:'14:01',date:'2026-11-20'},
      {id:'m7',channel:'c3',author:'u3',text:'Yes, core platform features are usable immediately. Optional integration work can happen later.',time:'14:10',date:'2026-11-20'},
      {id:'m8',channel:'c4',author:'u4',text:'Let’s review the contract wording before documenting our final conclusion.',time:'16:11',date:'2026-11-20'},
      {id:'m9',channel:'c4',author:'u5',text:'Agreed. The technical assessment should distinguish the software access from optional services.',time:'16:18',date:'2026-11-20'},
      {id:'m10',channel:'c5',author:'u1',text:'We need the revised lease agreement and an updated payment schedule.',time:'09:15',date:'2026-11-18'},
      {id:'m11',channel:'c6',author:'u6',text:'Please prepare cash-flow forecasts and document impairment indicators.',time:'13:20',date:'2026-11-22'}
    ],
    evidence:[
      {id:'EV-001',workspace:'w1',kind:'message',source:'m2',channel:'c1',name:'Software availability and implementation scope',content:'The software is available to the customer on delivery. Implementation services are scoped separately in the statement of work.',status:'approved',approvedBy:'u1',approvedAt:'2026-11-19',proposedBy:'u1'},
      {id:'EV-002',workspace:'w1',kind:'message',source:'m5',channel:'c2',name:'Optional service termination clause',content:'The draft agreement permits separate termination of optional implementation services under clause 8.2, subject to notice. Legal has not yet completed its final review.',status:'pending',proposedBy:'u2'}
    ],
    files:[
      {id:'f1',workspace:'w1',channel:'c1',name:'Implementation_SOW_notes.txt',size:246,addedBy:'u3',extracted:'Scope of work notes: Implementation services are presented separately from software subscription fees. Optional integration work is priced independently.',uploaded:'2026-11-19',evidenceId:null}
    ],
    versions:{w1:[],w2:[],w3:[]},
    activities:[{workspace:'w1',type:'check',text:'Ava created the initial evidence baseline',when:'19 Nov'},{workspace:'w1',type:'chat',text:'Daniel proposed private evidence EV-002',when:'20 Nov'}],seq:20
  }}
  let state;
  try{state=JSON.parse(localStorage.getItem(STORE_KEY))||initialState()}catch{state=initialState()}
  let ui={modal:null,edit:false,editSections:null,compare:false,selectedHistory:null,busy:false,api:false,modelReady:false,chatOpen:false,sidebarCollapsed:window.matchMedia('(max-width: 670px)').matches,search:''};
  const $=sel=>document.querySelector(sel);
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true"><use href="#i-${name}"></use></svg>`;
  const who=id=>users.find(x=>x.id===id)||users[0];
  const initials=name=>name.split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();
  const avatar=(u,cl='')=>`<span class="avatar ${esc((u||{}).color||'green')} ${cl}">${esc(initials((u||{}).name||'?'))}</span>`;
  const user=()=>who(state.user);
  const workspace=()=>state.workspaces.find(x=>x.id===state.workspace);
  const myWorkspaces=()=>state.workspaces.filter(w=>w.members.includes(state.user)&&w.org===user().org);
  const owner=()=>workspace()&&workspace().owner===state.user;
  const channel=()=>state.conversations.find(c=>c.id===state.channel);
  const isChannelMember=c=>c&&c.workspace===state.workspace&&(c.kind==='general'?workspace().members.includes(state.user):c.members.includes(state.user));
  const channels=()=>state.conversations.filter(c=>c.workspace===state.workspace&&isChannelMember(c));
  const evidenceForWorkspace=()=>state.evidence.filter(e=>e.workspace===state.workspace&&(e.status==='approved'||isChannelMember(state.conversations.find(c=>c.id===e.channel))));
  const approved=()=>state.evidence.filter(e=>e.workspace===state.workspace&&e.status==='approved');
  const selectedVersion=()=>{const vs=state.versions[state.workspace]||[];return vs.find(v=>v.id===ui.selectedHistory)||vs[vs.length-1]};
  const now=()=>new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});
  const today=()=>new Date().toISOString().slice(0,10);
  const persist=()=>{try{localStorage.setItem(STORE_KEY,JSON.stringify(state))}catch{console.warn('Demo browser storage is unavailable in this context.')} };
  let toastTimer;
  function toast(t){const el=$('#toast');if(!el)return;el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3300)}
  function chooseWorkspace(id){const w=state.workspaces.find(w=>w.id===id);if(!w||!w.members.includes(state.user))return;state.workspace=id;state.view='workspace';state.tab='memo';state.channel=(state.conversations.find(c=>c.workspace===id&&c.kind==='general')||{}).id;ui.selectedHistory=null;ui.compare=false;ui.edit=false;ui.chatOpen=false;persist();render()}
  function chooseUser(id){if(!users.some(x=>x.id===id))return;state.user=id;const current=workspace();if(!current||!current.members.includes(id)||current.org!==user().org){state.workspace=myWorkspaces()[0]?.id||null}state.channel=(state.conversations.find(c=>c.workspace===state.workspace&&c.kind==='general')||{}).id;state.view='workspace';state.tab='memo';ui.selectedHistory=null;ui.chatOpen=false;ui.modal=null;ui.compare=false;persist();render();toast(`Viewing as ${user().name} (demo identity switch)`) }
  function renderSidebar(){return `<aside class="left-sidebar" aria-label="Workspace navigation"><div class="sidebar-head"><div class="brand"><div class="brandmark">t<span style="font-size:13px">m</span></div><div><div class="brandname">TechMemo<span style="color:#89d6b5">.</span></div><div class="brand-sub">Accounting workspace</div></div></div><button class="sidebar-toggle" data-action="toggle-sidebar" aria-controls="sidebar-navigation" aria-expanded="${!ui.sidebarCollapsed}" aria-label="${ui.sidebarCollapsed?'Expand sidebar':'Collapse sidebar'}" title="${ui.sidebarCollapsed?'Expand sidebar':'Collapse sidebar'}">${icon('panel')}</button></div><div id="sidebar-navigation" class="sidebar-scroll" ${ui.sidebarCollapsed?'inert':''}>
    <button class="org-switch" data-action="personas"><span class="org-icon">${esc(initials(state.organizations.find(o=>o.id===user().org)?.name||'Org'))}</span><span class="grow truncate"><strong class="truncate">${esc(state.organizations.find(o=>o.id===user().org)?.name||'Organization')}</strong><small>Demo organization</small></span>${icon('chevron')}</button>
    <button class="side-link ${state.view==='dashboard'?'active':''}" data-action="dashboard">${icon('grid')}<span>Overview</span></button>
    <div class="sidebar-section-head"><span>Accounting workspaces</span><button aria-label="Create workspace" class="icon-btn" data-action="new-workspace">${icon('plus')}</button></div>
    <div class="workspaces-list">${myWorkspaces().map(w=>`<button class="workspace-card ${state.workspace===w.id&&state.view==='workspace'?'active':''}" data-action="workspace" data-id="${w.id}"><span class="workspace-icon">${icon('file')}</span><span class="grow"><span class="workspace-name">${esc(w.name)}</span><span class="workspace-meta">${esc(w.code)} · ${esc(w.standard)}</span></span></button>`).join('')}</div>
    <button class="side-link" data-action="new-workspace">${icon('plus')}<span>New accounting issue</span></button>
    <div class="sidebar-spacer"></div><div class="sidebar-tip"><strong>${icon('shield')} Private by design</strong>Only invited employees can join an issue. Private messages never become shared AI evidence without approval.</div>
    </div><div id="workspace-account"><button class="persona-btn" data-action="personas">${avatar(user())}<span class="grow"><span class="person-name">${esc(user().name)}</span><br><span class="person-role">${esc(user().role)}</span></span>${icon('chevron')}</button></div>
  </aside>`}
  function topbar(){const w=workspace();return `<header class="topbar"><div class="crumbs"><span class="trunc-mobile">Workspaces</span><span class="trunc-mobile">/</span><strong class="truncate">${esc(state.view==='dashboard'?'Overview':w?.name||'No workspace')}</strong></div><div class="top-actions"><button class="icon-btn mobile-chat-toggle" data-action="dashboard" title="Workspace overview" aria-label="Workspace overview">${icon('grid')}</button><span class="model-status" title="${ui.api?'Hugging Face backend detected; models load when needed':'No backend detected. Local template generation only.'}"><span class="status-dot ${ui.api?'online':''}"></span>${ui.api?'Hugging Face backend':'Offline template mode'}</span><button class="icon-btn mobile-chat-toggle" aria-label="Open conversations" data-action="toggle-chat">${icon('chat')}</button>${avatar(user(),'tiny')}</div></header>`}
  function renderDashboard(){return `<div class="main-scroll"><div class="eyebrow">YOUR ORGANIZATION</div><div class="overview-row"><div><h1 class="page-title">Good to see you, ${esc(user().name.split(' ')[0])}</h1><div class="page-subtitle">Your invited accounting workspaces in ${esc(state.organizations.find(o=>o.id===user().org)?.name)}.</div></div><button class="btn primary" data-action="new-workspace">${icon('plus')} New issue</button></div><div class="dash-grid">${myWorkspaces().map(w=>`<button class="dash-tile" data-action="workspace" data-id="${w.id}"><span class="tag">${esc(w.standard)}</span><h3>${esc(w.name)}</h3><p>${esc(w.description)}</p><span class="tag gray">${esc(w.members.length)} invited members</span></button>`).join('')||'<div class="empty-state">No invited workspaces yet.</div>'}</div><div class="model-warning" style="margin-top:25px">Prototype mode: users and permissions are simulated in browser storage. Production SSO, secure multi-tenant isolation and server-side authorization are not yet implemented.</div></div>`}
  function renderIssue(){const w=workspace();if(!w)return '';return `<div class="issue-card"><div class="issue-top"><div><div class="issue-header">${icon('info')} Accounting issue <span class="tag gray">${esc(w.code)}</span></div><p class="issue-copy">${esc(w.description)}</p></div><span class="tag ${w.status==='Draft'?'amber':''}">${esc(w.status)}</span></div><div class="issue-foot"><div class="action-row"><span class="muted-detail">Standard <strong>${esc(w.standard)}</strong></span><span class="muted-detail">Reporting period <strong>${esc(w.date)}</strong></span></div><div class="action-row"><div class="member-avatars">${w.members.slice(0,5).map(id=>avatar(who(id),'tiny')).join('')}<span class="member-count">${w.members.length} members</span></div>${owner()?`<button class="btn small" data-action="invite">${icon('plus')} Invite</button>`:''}</div></div></div>`}
  function renderMain(){if(state.view==='dashboard')return renderDashboard();const w=workspace();if(!w)return `<div class="main-scroll"><div class="empty-state"><h3>Not invited to a workspace</h3><p>Create a new issue to get started.</p><button class="btn primary" data-action="new-workspace">New issue</button></div></div>`;
    return `<div class="main-scroll"><div class="overview-row"><div><div class="eyebrow">ACCOUNTING / ${esc(w.code)}</div><h1 class="page-title">${esc(w.name)}</h1><div class="page-subtitle">Collaborate on the facts, research the guidance, and refine the technical conclusion.</div></div><div class="action-row"><button class="btn" data-action="invite">${icon('users')} Members</button><button class="btn primary" data-action="generate" ${ui.busy?'disabled':''}>${ui.busy?'<span class="progress-spinner"></span>':icon('spark')}${ui.busy?'Generating…':'Generate draft'}</button></div></div>
    ${renderIssue()}<div class="section-toolbar"><div class="tabbar"><button class="tab ${state.tab==='memo'?'active':''}" data-action="tab" data-id="memo">${icon('file')} Memo editor</button><button class="tab ${state.tab==='evidence'?'active':''}" data-action="tab" data-id="evidence">${icon('folder')} Evidence <span class="tag gray">${evidenceForWorkspace().length}</span></button><button class="tab ${state.tab==='activity'?'active':''}" data-action="tab" data-id="activity">${icon('clock')} Activity</button></div></div>
    ${state.tab==='memo'?renderMemo():state.tab==='evidence'?renderEvidence():renderActivity()}
    </div>`}
  function renderMemo(){const v=selectedVersion();const count=(state.versions[state.workspace]||[]).length;
    return `<div class="document-wrap"><div class="doc-bar"><div><div class="doc-name">${icon('file')} Technical accounting memorandum ${v?`<span class="tag">Version ${v.number}</span>`:'<span class="tag amber">Not generated</span>'}</div><div class="doc-meta">${v?`${esc(v.reason)} · ${esc(v.date)} · ${esc(v.method)}`:'Generate a first draft from approved case evidence'}</div></div><div class="doc-tools"><button class="btn small" data-action="history" title="Version history">${icon('history')} <span class="trunc-mobile">History</span></button>${v?`<button class="btn small" data-action="compare" title="Compare versions">${icon('branch')} Compare</button><button class="btn small" data-action="edit" title="Edit memo">${icon('edit')} ${ui.edit?'Cancel':'Edit'}</button><button class="btn small" data-action="export" title="Export Markdown">${icon('download')}</button>`:''}</div></div>
    ${v?`<article class="document"><h2>Technical accounting memorandum</h2><p class="doc-intro">${esc(workspace().code)} · ${esc(workspace().standard)} · ${esc(workspace().date)} · Working draft — requires professional review</p>${v.sections.map((s,i)=>`<section class="memo-section"><h3><span class="section-number">${String(i+1).padStart(2,'0')}</span>${esc(s.title)}</h3>${ui.edit?`<textarea data-section="${esc(s.id)}" aria-label="Edit ${esc(s.title)}">${esc((ui.editSections||v.sections).find(x=>x.id===s.id)?.body??s.body)}</textarea>`:`<p>${esc(s.body)}</p>`}</section>`).join('')}
      ${ui.edit?`<div class="action-row"><button class="btn primary" data-action="save-edit">${icon('check')} Save as new version</button><button class="btn" data-action="edit">Cancel</button></div>`:''}
      <div class="model-warning"><strong>${v.method==='GPT-2 + MiniLM-L6-v2'?'Hugging Face experimental model':'Local template preview'}:</strong> ${v.method==='GPT-2 + MiniLM-L6-v2'?'GPT-2 continuation is unverified and may be incoherent or inaccurate. ':'This draft is assembled from a deterministic outline, not an AI model. '}Neither output is authoritative accounting advice. Validate facts, guidance, and conclusions before use.</div>
      ${renderSources(v)}</article>`:`<div class="empty-state"><div class="empty-icon">${icon('spark')}</div><h3>Your accounting memo starts here</h3><p>Approve evidence from your discussion, then generate an initial memo. Future drafts will preserve earlier versions and show what changed.</p><button class="btn primary" data-action="generate">${icon('spark')} Generate first draft</button></div>`}
    </div>${ui.compare?renderComparison():''}`}
  function renderSources(v){const w=workspace(),s=STANDARDS[w.standard]||STANDARDS['IFRS 15'];return `<div class="memo-section"><h3>Research & source trail</h3><div class="source-list">${v.evidenceIds.length?`Evidence: ${v.evidenceIds.map(id=>`<span class="tag gray">${esc(id)}</span>`).join(' ')}`:'No approved evidence snapshot'}<br>Standards reference: <a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)} ${icon('external')}</a><br>Secondary guidance: <a href="${esc(s.secondary)}" target="_blank" rel="noopener noreferrer">IAS Plus resource ${icon('external')}</a><br><em>External links are research starting points, not retrieved or verified paragraph citations.</em></div></div>`}
  function renderComparison(){const vs=state.versions[state.workspace]||[];const idx=vs.findIndex(x=>x.id===selectedVersion()?.id),current=vs[Math.max(0,idx)],prev=vs[idx-1];return `<div class="document-wrap" style="margin-top:17px"><div class="doc-bar"><div><div class="doc-name">${icon('branch')} Version comparison</div><div class="doc-meta">${prev?`Version ${prev.number} → Version ${current.number}`:'Generate or save a second version to compare changes'}</div></div><button class="icon-btn" data-action="compare">${icon('close')}</button></div>${!prev?'<div class="diff-none">No earlier version available for this selected version.</div>':`<div class="diff-view">${current.sections.map(s=>{const old=prev.sections.find(p=>p.id===s.id)?.body||'';return old!==s.body?`<div class="diff-section"><h4>${esc(s.title)}</h4><div class="diff-old">− ${esc(old||'(section did not exist)')}</div><div class="diff-new">+ ${esc(s.body)}</div></div>`:''}).join('')||'<div class="diff-none">No text changes between these versions.</div>'}</div>`}</div>`}
  function renderEvidence(){const w=workspace(),e=evidenceForWorkspace(),pending=e.filter(x=>x.status==='pending'),files=state.files.filter(f=>f.workspace===w.id&&(f.channel==null||isChannelMember(state.conversations.find(c=>c.id===f.channel))||state.evidence.some(x=>x.source===f.id&&x.status==='approved')));
    return `<div class="evidence-stats"><div class="stat-card"><div class="number">${approved().length}</div><div class="label">Approved evidence</div></div><div class="stat-card"><div class="number">${pending.length}</div><div class="label">Pending approval (visible to you)</div></div><div class="stat-card"><div class="number">${files.length}</div><div class="label">Accessible attachments</div></div></div><div class="section-toolbar"><div><h2 style="font-size:16px;margin:0">Evidence library</h2><div class="page-subtitle" style="margin-top:6px">Only approved excerpts and attachments can inform memo generation.</div></div><button class="btn" data-action="upload">${icon('clip')} Upload file</button></div><div class="evidence-list">${e.map(item=>`<div class="evidence-card"><div class="file-icon">${icon(item.kind==='file'?'file':'chat')}</div><div class="grow"><div class="evidence-title">${esc(item.name)} <span class="tag ${item.status==='approved'?'':'amber'}">${item.status==='approved'?'Approved':'Awaiting approval'}</span></div><div class="evidence-desc">${esc(item.content||'Attachment received; no extracted text available.')}<br>Source: ${item.kind==='message'?'Conversation excerpt':'File'} · Proposed by ${esc(who(item.proposedBy).name)} ${item.status==='approved'?`· Approved by ${esc(who(item.approvedBy).name)}`:''}</div></div><div class="evidence-actions">${item.status==='pending'&&owner()?`<button class="btn primary small" data-action="approve" data-id="${item.id}">${icon('check')} Approve</button>`:''}${item.status==='pending'&&item.proposedBy===state.user?`<button class="btn small danger" data-action="withdraw" data-id="${item.id}">Withdraw</button>`:''}</div></div>`).join('')||`<div class="empty-state"><h3>No visible evidence yet</h3><p>Use “Propose as evidence” on a message, or upload a file.</p></div>`}</div><div class="small-overline">Attachments</div><div class="evidence-list">${files.map(f=>`<div class="evidence-card"><div class="file-icon">${icon('file')}</div><div class="grow"><div class="evidence-title">${esc(f.name)}</div><div class="evidence-desc">Added by ${esc(who(f.addedBy).name)} · ${Math.ceil((f.size||0)/1024)} KB · ${esc(f.extracted?'Text available for review':'Content not extracted; metadata only')}</div></div><div class="evidence-actions">${!state.evidence.some(x=>x.source===f.id)?`<button class="btn small" data-action="propose-file" data-id="${f.id}">Propose</button>`:''}</div></div>`).join('')||'<span class="disclaimer">No attachments yet.</span>'}</div><div class="model-warning">Privacy rule: approving content for memo evidence shares only that selected content. It does not disclose the private thread. This demo stores data in your browser; it is not secure enterprise storage.</div>`}
  function renderActivity(){const logs=state.activities.filter(a=>a.workspace===state.workspace).slice().reverse();return `<div class="activity">${logs.map(x=>`<div class="activity-row"><div class="icon-wrap">${icon(x.type==='check'?'shield':x.type==='chat'?'chat':'history')}</div><div class="grow"><strong>${esc(x.text)}</strong><p>${esc(x.when||'Just now')}</p></div></div>`).join('')||'<p class="disclaimer">No activity yet.</p>'}</div>`}
  function renderChat(){const w=workspace();if(!w||state.view==='dashboard')return `<aside class="right-panel ${ui.chatOpen?'open':''}"><div class="right-head"><strong>Conversations</strong><button class="icon-btn" data-action="toggle-chat">${icon('close')}</button></div><div class="conversation-empty">Open an accounting workspace to view its discussions.</div></aside>`;
    const ch=isChannelMember(channel())?channel():channels()[0],msgs=ch?state.messages.filter(m=>m.channel===ch.id):[];
    const publics=channels().filter(x=>x.kind==='general'),directs=channels().filter(x=>x.kind==='direct'),groups=channels().filter(x=>x.kind==='group');
    const cbtn=c=>`<button class="channel-item ${ch&&ch.id===c.id?'selected':''}" data-action="channel" data-id="${c.id}">${icon(c.kind==='general'?'chat':c.kind==='direct'?'lock':'users')}<span class="channel-name">${esc(c.kind==='direct'?who(c.members.find(i=>i!==state.user)||state.user).name:c.name)}</span></button>`;
    return `<aside class="right-panel ${ui.chatOpen?'open':''}"><div class="right-head"><div class="right-title">${icon('chat')} Conversations</div><div class="action-row"><button class="icon-btn" title="New private conversation" data-action="new-chat">${icon('plus')}</button><button class="icon-btn mobile-chat-toggle" data-action="toggle-chat">${icon('close')}</button></div></div><div class="right-body"><div class="channel-section"><div class="section-label">Shared channel</div>${publics.map(cbtn).join('')}<div class="section-label" style="margin-top:14px">Direct messages <button class="icon-btn" data-action="new-chat" title="New private chat">${icon('plus')}</button></div>${directs.map(cbtn).join('')||'<span class="disclaimer">No private messages</span>'}<div class="section-label" style="margin-top:14px">Private groups <button class="icon-btn" data-action="new-group" title="New private group">${icon('plus')}</button></div>${groups.map(cbtn).join('')||'<span class="disclaimer">No private groups</span>'}</div><div class="chat-section"><div class="chat-header"><div><strong>${icon(ch?.kind==='general'?'users':'lock')} ${esc(ch?.kind==='direct'?who(ch.members.find(i=>i!==state.user)||state.user).name:ch?.name||'Discussion')}</strong><small>${ch?.kind==='general'?'Visible to all invited members':`Private · ${ch?.members.length||0} participants`}</small></div><span class="tag ${ch?.kind==='general'?'':'amber'}">${ch?.kind==='general'?'Shared':'Private'}</span></div>
    <div class="messages" id="messages">${msgs.map(m=>renderMessage(m,ch)).join('')||'<div class="conversation-empty">No messages yet. Start the conversation.</div>'}</div><div class="chat-compose"><form id="send-form"><div class="compose-box"><textarea id="message-input" placeholder="Message ${esc(ch?.kind==='general'?'the team':'privately')}…" aria-label="Message text" required></textarea><div class="compose-actions"><button type="button" class="icon-btn" data-action="attach" title="Attach a file">${icon('clip')}</button><button type="submit" class="send-btn" aria-label="Send message">${icon('send')}</button></div></div></form><div class="compose-hint">${icon('shield')} ${ch?.kind==='general'?'Shared channel · facts should be verified':'Private messages are excluded from memo AI until approved'}</div></div></div></div></aside>`}
  function renderMessage(m,ch){const u=who(m.author),mine=m.author===state.user,ev=state.evidence.find(e=>e.source===m.id);return `<div class="message ${mine?'mine':''}">${avatar(u,'tiny')}<div class="message-content"><div class="message-top"><span class="message-author">${esc(u.name.split(' ')[0])}</span><span class="message-time">${esc(m.time)}</span></div><div class="bubble">${esc(m.text)}${m.file?`<span class="message-file">${icon('clip')} ${esc(m.file)}</span>`:''}</div><div class="message-actions">${ev?`<span class="tag ${ev.status==='pending'?'amber':''}">${ev.status==='approved'?'Evidence approved':'Evidence pending'}</span>`:`<button class="text-action" data-action="propose-message" data-id="${m.id}">${icon('plus')} Propose as evidence</button>`}</div></div></div>`}
  function renderModal(){if(!ui.modal)return '';const m=ui.modal;const head=title=>`<div class="modal-overlay" data-action="overlay"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}" ><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close">${icon('close')}</button></div>`;const foot=(button,label,disabled='')=>`<div class="modal-foot"><button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="${button}" ${disabled}>${label}</button></div></div></div>`;
    if(m.type==='personas')return `${head('Switch demo identity')}<div class="modal-body"><p class="disclaimer">Identity switching simulates different employee views. It is not authentication, SSO, or an enterprise security boundary.</p>${users.map(u=>`<button class="persona-option" data-action="switch-user" data-id="${u.id}">${avatar(u)}<span class="grow"><strong>${esc(u.name)}</strong><br><span class="disclaimer">${esc(u.role)} · ${esc(state.organizations.find(o=>o.id===u.org)?.name)}</span></span>${u.id===state.user?icon('check'):icon('arrow')}</button>`).join('')}</div></div></div>`;
    if(m.type==='new-workspace')return `${head('Create accounting workspace')}<div class="modal-body"><div class="form-field"><label>Issue title</label><input id="new-title" placeholder="e.g. Revenue recognition assessment" maxlength="100"/></div><div class="form-field"><label>Accounting issue / question</label><textarea id="new-description" placeholder="Describe the transaction and what needs to be determined…"></textarea></div><div class="form-field"><label>Applicable framework</label><select id="new-standard">${Object.keys(STANDARDS).map(x=>`<option value="${x}">${esc(STANDARDS[x].label)}</option>`).join('')}</select></div><div class="form-field"><label>Reporting period</label><input id="new-period" value="FY 2026"/></div><p class="field-help">The new issue will be visible only to you until you invite colleagues.</p></div>${foot('create-workspace','Create workspace')}`;
    if(m.type==='invite'){const w=workspace(),opts=users.filter(u=>u.org===w.org&&!w.members.includes(u.id));return `${head('Manage workspace members')}<div class="modal-body"><p class="disclaimer">Only employees of ${esc(state.organizations.find(o=>o.id===w.org)?.name)} can be invited. Production SSO must verify actual organization membership.</p><div class="small-overline">CURRENT MEMBERS</div>${w.members.map(id=>`<div class="persona-option" style="cursor:default">${avatar(who(id))}<span class="grow"><strong>${esc(who(id).name)}</strong><br><span class="disclaimer">${esc(who(id).role)}</span></span>${w.owner===id?'<span class="tag">Owner</span>':''}</div>`).join('')}${owner()?`<div class="small-overline">INVITE AN EMPLOYEE</div>${opts.length?opts.map(u=>`<button class="persona-option" data-action="invite-user" data-id="${u.id}">${avatar(u)}<span class="grow"><strong>${esc(u.name)}</strong><br><span class="disclaimer">${esc(u.role)}</span></span>${icon('plus')}</button>`).join(''):'<p class="disclaimer">All demo employees are already members.</p>'}`:''}</div></div></div>`}
    if(m.type==='new-chat'){const w=workspace();const others=w.members.filter(id=>id!==state.user&&(!owner()?id===w.owner:true));return `${head('Start private direct message')}<div class="modal-body"><p class="disclaimer">A direct message is visible only to its participants. The workspace owner participates in each direct message in this prototype.</p>${others.map(id=>`<button class="persona-option" data-action="create-direct" data-id="${id}">${avatar(who(id))}<span class="grow"><strong>${esc(who(id).name)}</strong><br><span class="disclaimer">${esc(who(id).role)}</span></span>${icon('arrow')}</button>`).join('')||'<p class="disclaimer">Invite more employees to start a private discussion.</p>'}</div></div></div>`}
    if(m.type==='new-group'){const w=workspace();return `${head('Create private group')}<div class="modal-body"><div class="form-field"><label>Group name</label><input id="group-name" maxlength="70" placeholder="e.g. Legal and finance review"/></div><div class="form-field"><label>Select members</label><div class="choice-list">${w.members.filter(id=>id!==state.user&&id!==w.owner).map(id=>`<label class="choice"><input type="checkbox" class="group-member" value="${id}"/>${avatar(who(id))}<span><strong>${esc(who(id).name)}</strong><small>${esc(who(id).role)}</small></span></label>`).join('')}</div></div><p class="field-help">You and the workspace owner will be included. Only participants can read this group's messages.</p></div>${foot('create-group','Create private group')}`}
    if(m.type==='propose'){return `${head('Propose evidence for memo')}<div class="modal-body"><p class="disclaimer">Review the exact excerpt that would be shared. Private conversations remain hidden; this selected content is released only after the workspace owner approves.</p><div class="form-field"><label>Evidence label</label><input id="evidence-name" value="${esc(m.name)}"/></div><div class="form-field"><label>Selected content (editable)</label><textarea style="min-height:135px" id="evidence-content">${esc(m.content)}</textarea></div><div class="danger-note">${icon('lock')} This action submits a proposal only. It does not grant memo-generation access until explicit approval.</div></div>${foot('submit-evidence','Submit for approval')}`}
    if(m.type==='approve'){const e=state.evidence.find(x=>x.id===m.id);return `${head('Approve selected evidence')}<div class="modal-body"><p class="disclaimer">Confirm that this selected material may be used by TechMemo's memo generator and included in the shared memo. The rest of the private conversation stays private.</p><div class="form-field"><label>Selected evidence</label><div class="review-box">${esc(e?.content||'')}</div></div><div class="danger-note">Approval makes this excerpt visible in the shared evidence library and potentially in memo versions. Verify it contains no material that should remain confidential.</div></div>${foot('confirm-approve',`${icon('shield')} Approve & share`)}`}
    if(m.type==='history'){const vs=(state.versions[state.workspace]||[]).slice().reverse();return `${head('Memo version history')}<div class="modal-body"><p class="disclaimer">Select a version to preview. Saving changes creates a new version without overwriting prior snapshots.</p><div class="version-list">${vs.map(v=>`<div class="version-row ${(selectedVersion()?.id===v.id)?'active':''}"><div><strong>Version ${v.number} · ${esc(v.reason)}</strong><p>${esc(v.date)} · ${esc(v.method)} · ${esc(v.evidenceIds.length)} evidence item(s)</p></div><button class="btn small" data-action="select-version" data-id="${v.id}">View</button></div>`).join('')||'<div class="diff-none">No versions yet.</div>'}</div></div></div>`}
    if(m.type==='export')return `${head('Export memorandum')}<div class="modal-body"><p class="disclaimer">Download a Markdown memo that includes source links and version metadata. Word/PDF export can be added in a later build.</p></div>${foot('confirm-export',`${icon('download')} Download .md`)}`;
    if(m.type==='upload'){return `${head('Upload supporting evidence')}<div class="modal-body"><p class="disclaimer">Upload a file to the current conversation. Private attachments remain restricted to conversation members and require approval before use in a memo.</p><div class="form-field"><label>File</label><input type="file" id="upload-file" accept=".txt,.md,.csv,.json,.pdf,.docx,.xlsx,.xls"/></div><div class="field-help">Text files can be read directly; with the optional Python server, PDF, DOCX and XLSX text extraction is available. Files in this demo are not persisted as secure binary storage.</div></div>${foot('confirm-upload','Attach file')}`}
    return '';
  }
  function render(){const app=$('#app');app.innerHTML=`<div class="app-shell ${ui.sidebarCollapsed?'sidebar-collapsed':''}">${renderSidebar()}<main class="main">${topbar()}${renderMain()}</main>${renderChat()}</div>${renderModal()}<input id="hidden-attach" type="file" accept=".txt,.md,.csv,.json,.pdf,.docx,.xlsx,.xls" hidden>`;if(state.view==='workspace'){const box=$('#messages');if(box)box.scrollTop=box.scrollHeight}window.dispatchEvent(new Event('techmemo:workspace-render'))}
  function addActivity(text,type='history'){state.activities.push({workspace:state.workspace,type,text,when:today()})}
  function makeEvidence({kind,source,channel:ch,name,content}){const id=`EV-${String(++state.seq).padStart(3,'0')}`;state.evidence.push({id,workspace:state.workspace,kind,source,channel:ch,name,content,status:'pending',proposedBy:state.user});addActivity(`${user().name} proposed evidence ${id}`,'chat');persist();ui.modal=null;state.tab='evidence';render();toast('Evidence proposal submitted. Owner approval required.')}
  function draftSections(w,items,experimental=''){const st=STANDARDS[w.standard]||STANDARDS['IFRS 15'];const body=items.length?items.map(e=>`[${e.id}] ${e.content||'[Attachment text not extracted]'}`).join('\n\n'):'No evidence has been approved yet.';return [
    {id:'purpose',title:'Purpose and accounting issue',body:`This working paper evaluates the following matter for ${w.date}: ${w.description}\nThe assessment is prepared under ${w.standard} and remains subject to professional review.`},
    {id:'facts',title:'Background and relevant facts',body:`The following facts have been selected and approved for use in this memo:\n\n${body}\n\nNo unapproved private messages were considered.`},
    {id:'guidance',title:'Relevant accounting framework',body:`Relevant research starting point: ${st.label}.\n\nResearch focus: ${st.focus}\n\nThe applicable authoritative paragraphs, amendments and effective-date requirements must be independently retrieved and verified before a final position is reached.`},
    {id:'analysis',title:'Preliminary technical analysis',body:`Apply the relevant ${w.standard} criteria to each verified contract or transaction fact above. In particular, reconcile evidence IDs ${items.map(e=>e.id).join(', ')||'—'} with the requirements and identify information that may support or contradict alternative accounting treatments.\n\nThe available evidence alone should not be treated as a definitive determination. Confirm relevant contract rights, obligations, transaction economics, and any significant judgments.`},
    {id:'conclusion',title:'Preliminary conclusion',body:`An accounting conclusion has not been finalized. Subject to validation of the underlying facts and the applicable authoritative ${w.standard} guidance, the accounting manager should document the appropriate treatment and obtain reviewer approval.`},
    {id:'open',title:'Open questions and next steps',body:`• Confirm completeness and accuracy of approved facts and related agreements.\n• Check the exact applicable standards paragraphs and effective dates.\n• Resolve any contradictory evidence or missing information.\n• Document and obtain approval for the final accounting treatment.`},
    ...(experimental?[{id:'experimental',title:'GPT-2 experimental continuation — unverified',body:experimental}]:[])
  ]}
  async function generate(){if(!workspace()||ui.busy)return;const w=workspace(),items=approved();if(!items.length){toast('Approve at least one evidence item before generating a draft.');state.tab='evidence';render();return}ui.busy=true;render();let experimental='',retrieved=[],method='Local template';try{if(ui.api){const url=apiUrl('/api/generate');const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({issue:w.description,standard:w.standard,evidence:items.map(e=>({id:e.id,text:e.content})),max_new_tokens:75})});if(!r.ok)throw new Error((await r.json().catch(()=>({detail:'Model request failed'}))).detail||'Model request failed');const data=await r.json();experimental=data.gpt2_continuation||'';retrieved=data.retrieval||[];method='GPT-2 + MiniLM-L6-v2'} }catch(err){toast(`Model backend unavailable; using local template. ${String(err.message).slice(0,75)}`)}
    const vs=state.versions[w.id]||[];vs.push({id:`v${Date.now()}-${state.seq++}`,number:vs.length+1,reason:'Generated draft',date:new Date().toLocaleString(),method,sections:draftSections(w,items,experimental),evidenceIds:items.map(e=>e.id),retrieval:retrieved});state.versions[w.id]=vs;state.tab='memo';ui.busy=false;ui.edit=false;ui.selectedHistory=null;ui.compare=vs.length>1;addActivity(`${user().name} generated memo version ${vs.length} (${method})`);persist();render();toast(`Memo version ${vs.length} generated ${ui.api&&method==='GPT-2 + MiniLM-L6-v2'?'with Hugging Face':'using local outline'}`)}
  function saveEdit(){const v=selectedVersion();if(!v)return;const updated=v.sections.map(s=>({...s,body:document.querySelector(`textarea[data-section="${s.id}"]`)?.value||''}));if(updated.every((s,i)=>s.body===v.sections[i].body)){ui.edit=false;render();toast('No changes made.');return}const vs=state.versions[state.workspace];vs.push({id:`v${Date.now()}-${state.seq++}`,number:vs.length+1,reason:`Edited by ${user().name}`,date:new Date().toLocaleString(),method:'Human edit',sections:updated,evidenceIds:[...v.evidenceIds]});ui.edit=false;ui.selectedHistory=null;ui.compare=true;addActivity(`${user().name} saved human edit as version ${vs.length}`);persist();render();toast('Edits saved as a new version')}
  function exportMemo(){const v=selectedVersion();if(!v)return;const w=workspace(),s=STANDARDS[w.standard]||STANDARDS['IFRS 15'];let txt=`# Technical accounting memorandum\n\nIssue: ${w.name} (${w.code})\nFramework: ${w.standard}\nReporting period: ${w.date}\nVersion: ${v.number}\nMethod: ${v.method}\n\n`;v.sections.forEach((sec,i)=>{txt+=`## ${i+1}. ${sec.title}\n\n${sec.body}\n\n`});txt+=`## Sources\n\nApproved evidence: ${v.evidenceIds.join(', ')}\n\nStandards research starting point: ${s.url}\nSecondary resource: ${s.secondary}\n\nUnverified draft for professional review.\n`;const blob=new Blob([txt],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${w.code}-memo-v${v.number}.md`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);ui.modal=null;render();toast('Markdown memo downloaded')}
  function apiUrl(path){return location.protocol==='file:'?`http://127.0.0.1:8000${path}`:path}
  async function checkBackend(){try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),1800);const resp=await fetch(apiUrl('/api/health'),{signal:controller.signal});clearTimeout(timer);const data=await resp.json();ui.api=!!data.ok;ui.modelReady=!!data.models_loaded}catch{ui.api=false}render()}
  async function attachFile(input){const file=input?.files?.[0];if(!file)return;if(file.size>12*1024*1024){toast('Demo attachment limit: 12 MB');return}let extracted='';const plain=/\.(txt|md|csv|json)$/i.test(file.name);try{if(plain){extracted=(await file.text()).slice(0,16000)}else if(ui.api){const form=new FormData();form.append('file',file);const r=await fetch(apiUrl('/api/extract'),{method:'POST',body:form});if(r.ok){const d=await r.json();extracted=(d.text||'').slice(0,16000)}else toast('File attached, but text extraction failed.')}else{toast('File added as metadata. Run Python backend to extract PDF/DOCX/XLSX text.')}}catch{toast('File attached without extracted text.')}const ch=channel(),id=`f${++state.seq}`;state.files.push({id,workspace:state.workspace,channel:ch?.id||null,name:file.name,size:file.size,addedBy:state.user,extracted,uploaded:today()});if(ch){state.messages.push({id:`m${++state.seq}`,channel:ch.id,author:state.user,text:`Uploaded ${file.name}. The file requires explicit approval before its contents can be used by the memo.`,file:file.name,time:now(),date:today()})}addActivity(`${user().name} attached ${file.name}`);persist();render();toast('Attachment added. Propose it from the Evidence tab to request approval.')}
  function addChannel(kind,name,members){const ch={id:`c${++state.seq}`,workspace:state.workspace,kind,name,members};state.conversations.push(ch);state.channel=ch.id;ui.modal=null;persist();render();toast('Private conversation created')}
  function clickAction(action,id){switch(action){
    case 'personas':ui.modal={type:'personas'};break;
    case 'switch-user':chooseUser(id);return;
    case 'toggle-sidebar':{ui.sidebarCollapsed=!ui.sidebarCollapsed;const shell=document.querySelector('.app-shell');shell.classList.toggle('sidebar-collapsed',ui.sidebarCollapsed);const toggle=document.querySelector('.sidebar-toggle');toggle.setAttribute('aria-expanded',String(!ui.sidebarCollapsed));toggle.setAttribute('aria-label',ui.sidebarCollapsed?'Expand sidebar':'Collapse sidebar');toggle.title=ui.sidebarCollapsed?'Expand sidebar':'Collapse sidebar';document.querySelector('#sidebar-navigation').inert=ui.sidebarCollapsed;return;}
    case 'dashboard':state.view='dashboard';break;
    case 'workspace':chooseWorkspace(id);return;
    case 'new-workspace':ui.modal={type:'new-workspace'};break;
    case 'create-workspace':{const name=$('#new-title')?.value.trim(),description=$('#new-description')?.value.trim();if(!name||!description){toast('Please enter a title and accounting question.');return}const standard=$('#new-standard').value,id=`w${++state.seq}`;state.workspaces.push({id,org:user().org,name,code:`ACC-2026-${String(state.seq).padStart(3,'0')}`,standard,status:'Draft',owner:state.user,date:$('#new-period')?.value||'FY 2026',description,members:[state.user],created:today()});state.versions[id]=[];state.conversations.push({id:`c${++state.seq}`,workspace:id,kind:'general',name:'General discussion',members:[]});ui.modal=null;chooseWorkspace(id);toast('Private workspace created');return}
    case 'invite':ui.modal={type:'invite'};break;
    case 'invite-user':if(!owner()){toast('Only the owner can invite employees.');return}if(!workspace().members.includes(id)&&who(id).org===workspace().org){workspace().members.push(id);addActivity(`${user().name} invited ${who(id).name}`);persist();toast(`${who(id).name} invited to the workspace`)}break;
    case 'channel':state.channel=id;ui.chatOpen=true;break;
    case 'new-chat':ui.modal={type:'new-chat'};break;
    case 'new-group':ui.modal={type:'new-group'};break;
    case 'create-direct':{const selected=id,existing=state.conversations.find(c=>c.workspace===state.workspace&&c.kind==='direct'&&c.members.includes(state.user)&&c.members.includes(selected));if(existing){state.channel=existing.id;ui.modal=null}else{const ownerId=workspace().owner;if(state.user!==ownerId&&selected!==ownerId){toast('Direct chats must include the issue owner in this demo.');return}addChannel('direct',who(selected).name,[state.user,selected])}break}
    case 'create-group':{const name=$('#group-name')?.value.trim();const checked=[...document.querySelectorAll('.group-member:checked')].map(x=>x.value);if(!name||!checked.length){toast('Enter a group name and select at least one colleague.');return}const members=[...new Set([state.user,workspace().owner,...checked])];addChannel('group',name,members);break}
    case 'tab':state.tab=id;ui.compare=false;break;
    case 'toggle-chat':ui.chatOpen=!ui.chatOpen;break;
    case 'attach':$('#hidden-attach').click();return;
    case 'upload':ui.modal={type:'upload'};break;
    case 'confirm-upload':{const f=$('#upload-file')?.files?.[0];if(!f){toast('Select a file first.');return}ui.modal=null;attachFile({files:[f]});break}
    case 'propose-message':{const m=state.messages.find(x=>x.id===id),ch=state.conversations.find(c=>c.id===m?.channel);if(!m||!isChannelMember(ch))return;ui.modal={type:'propose',kind:'message',source:m.id,channel:m.channel,name:`Fact from ${who(m.author).name}`,content:m.text};break}
    case 'propose-file':{const f=state.files.find(x=>x.id===id);if(!f)return;const ch=state.conversations.find(c=>c.id===f.channel);if(ch&&!isChannelMember(ch))return;ui.modal={type:'propose',kind:'file',source:f.id,channel:f.channel,name:f.name,content:f.extracted||`File ${f.name} uploaded; extracted contents not available. Please supply a reviewed fact from the document.`};break}
    case 'submit-evidence':{const name=$('#evidence-name')?.value.trim(),content=$('#evidence-content')?.value.trim();if(!name||!content){toast('Evidence needs a title and selected content.');return}makeEvidence({...ui.modal,name,content});return}
    case 'approve':{const e=state.evidence.find(x=>x.id===id);if(!owner()||!e||e.status!=='pending'){toast('Approval requires workspace owner permission.');return}ui.modal={type:'approve',id};break}
    case 'confirm-approve':{const e=state.evidence.find(x=>x.id===ui.modal.id);if(!owner()||!e)return;e.status='approved';e.approvedBy=state.user;e.approvedAt=today();addActivity(`${user().name} approved selected evidence ${e.id}`,'check');ui.modal=null;persist();toast(`Evidence ${e.id} approved for memo generation`);break}
    case 'withdraw':{const e=state.evidence.find(x=>x.id===id);if(e?.status==='pending'&&e.proposedBy===state.user){state.evidence=state.evidence.filter(x=>x.id!==id);persist();toast('Evidence proposal withdrawn')}break}
    case 'generate':generate();return;
    case 'history':ui.modal={type:'history'};break;
    case 'select-version':ui.selectedHistory=id;ui.modal=null;ui.edit=false;ui.compare=false;break;
    case 'compare':ui.compare=!ui.compare;break;
    case 'edit':ui.edit=!ui.edit;ui.editSections=null;break;
    case 'save-edit':saveEdit();return;
    case 'export':ui.modal={type:'export'};break;
    case 'confirm-export':exportMemo();return;
    case 'close-modal':ui.modal=null;break;
    case 'overlay':ui.modal=null;break;
    default:return;
  }persist();render()}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;if(action==='overlay'&&e.target.closest('.modal'))return;e.preventDefault();clickAction(action,id)});
  document.addEventListener('submit',e=>{if(e.target.id!=='send-form')return;e.preventDefault();const val=$('#message-input')?.value.trim(),ch=channel();if(!val||!isChannelMember(ch))return;state.messages.push({id:`m${++state.seq}`,channel:ch.id,author:state.user,text:val,time:now(),date:today()});persist();render()});
  document.addEventListener('change',e=>{if(e.target.id==='hidden-attach')attachFile(e.target)});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.modal){ui.modal=null;render()}if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)&&document.activeElement?.id==='message-input'){e.preventDefault();$('#send-form')?.requestSubmit()}});
  // Seed an illustrative memo version from *approved* general-channel evidence only.
  if((state.versions.w1||[]).length===0){const w=state.workspaces.find(x=>x.id==='w1'),items=state.evidence.filter(e=>e.workspace==='w1'&&e.status==='approved');state.versions.w1=[{id:'v-seed-1',number:1,reason:'Initial outline',date:'19 Nov 2026',method:'Local template',sections:draftSections(w,items),evidenceIds:items.map(x=>x.id)}];persist()}
  render();checkBackend();
})();
